import { Picker as SpPicker } from "@swc-react/picker";
import "./styles.css";

export function Select(props: React.ComponentProps<typeof SpPicker>) {
  return (
    <SpPicker
      {...props}
    />
  );
}

@layer serok {
  .serok-root sp-picker {
    --mod-picker-background-color-default: var(--spectrum-white);
    --mod-picker-background-color-hover: var(--spectrum-global-color-gray-50);
    --mod-picker-background-color-key-focus: var(--spectrum-global-color-gray-50);
    --mod-picker-background-color-hover-open: var(--spectrum-global-color-gray-100);
    --mod-picker-background-color-active: var(--spectrum-global-color-gray-50);
  }
}
